try{
  const rec=new Rec();rec.lang='nb-NO';rec.continuous=false;rec.interimResults=false;rec.maxAlternatives=1;
  return await new Promise(resolve=>{
    let finished=false;const timer=w.setTimeout(()=>finish({ok:false,error:'Vi fikk ikke høre spørsmålet. Prøv igjen.'}),20000);
    function finish(result){if(finished)return;finished=true;w.clearTimeout(timer);try{rec.stop()}catch{}resolve(result)}
    rec.onresult=e=>{const text=String(e.results?.[0]?.[0]?.transcript||'').trim();finish(text?{ok:true,text:text.slice(0,500)}:{ok:false,error:'Jeg fikk ikke med meg spørsmålet.'})};
